INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','عملت تحليل حمل وطلع خط باهت جداً، كده أنا حامل؟','سؤال بيوصلنا كتير من البنات في أول أيام التأخير.', @t2 - 60000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='عملت تحليل حمل وطلع خط باهت جداً، كده أنا حامل؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'التحليل المنزلي أدق إن أُجري بعد تأخر الدورة، ويفضّل بأول بول في الصباح. الخط الباهت غالباً يعني حملاً مبكراً، فأعيديه بعد يومين. تحليل الدم أدق، وفي الحمل الطبيعي المبكر يتضاعف الهرمون تقريباً كل يومين إلى ثلاثة أيام. طبيبك يفسر الأرقام مع السونار.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 30000 FROM questions WHERE dev='nabd-team' AND title='عملت تحليل حمل وطلع خط باهت جداً، كده أنا حامل؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','متى يبين نبض البيبي في السونار؟ 💓','سؤال يتكرر وايد: رحت الأسبوع 6 وما بان النبض وخفت.', @t2 - 120000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='متى يبين نبض البيبي في السونار؟ 💓');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يظهر النبض غالباً في السونار المهبلي من الأسبوع 6 إلى 7. إن لم يظهر في سونار مبكر فلا يعني ذلك مشكلة دائماً، فقد يكون الحمل أصغر من المتوقع، وغالباً يُعاد السونار بعد 7 إلى 14 يوماً لتأكيد الصورة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 90000 FROM questions WHERE dev='nabd-team' AND title='متى يبين نبض البيبي في السونار؟ 💓' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','واش التنقيط ديال الدم فالأول ديال الحمل عادي؟','سؤال كيتعاود بزاف عندنا.', @t2 - 180000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='واش التنقيط ديال الدم فالأول ديال الحمل عادي؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'أي نزيف في الحمل يحتاج تقييم الطبيب. إن كان النزيف غزيراً، أو معه ألم شديد أو دوخة، فتوجهي للطوارئ فوراً. التنقيط البسيط في بداية الحمل قد يحدث، لكن لا يُحكم عليه إلا بالكشف.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 150000 FROM questions WHERE dev='nabd-team' AND title='واش التنقيط ديال الدم فالأول ديال الحمل عادي؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','إيه التحاليل اللي لازم أعملها أول ما أعرف إني حامل؟','سؤال بيتكرر من الأمهات الجداد.', @t2 - 240000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='إيه التحاليل اللي لازم أعملها أول ما أعرف إني حامل؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'عادة تشمل: صورة الدم (الهيموجلوبين)، وفصيلة الدم وعامل الريسس، والسكر، وتحليل البول، والغدة الدرقية أحياناً، ومناعة الحصبة الألمانية، والتهاب الكبد ب والزهري وفيروس نقص المناعة. وقد يُطلب فيتامين د حسب البلد. يمكنك تسجيل نتائجك في قسم «صحتي».\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 210000 FROM questions WHERE dev='nabd-team' AND title='إيه التحاليل اللي لازم أعملها أول ما أعرف إني حامل؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','دمي سالب وزوجي موجب، شو لازم أعمل؟','سؤال كتير بيوصلنا عن حقنة Anti-D.', @t2 - 300000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='دمي سالب وزوجي موجب، شو لازم أعمل؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'إن كانت فصيلتك سالبة والأب موجب، فقد يُعطى لكِ حقنة Anti-D حوالي الأسبوع 28، وبعد الولادة إن كان الطفل موجباً، وبعد أي نزيف أو إجهاض. هذه الحقنة تحمي حملك الحالي والقادم من مشكلات عدم توافق الدم.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 270000 FROM questions WHERE dev='nabd-team' AND title='دمي سالب وزوجي موجب، شو لازم أعمل؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','عندي قطوة بالبيت، لازم أبعدها وأنا حامل؟ 🐱','سؤال يتكرر كثير عن داء القطط.', @t2 - 360000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='عندي قطوة بالبيت، لازم أبعدها وأنا حامل؟ 🐱');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'لا تحتاجين للتخلص من قطتك. اجعلي غيرك ينظف صندوق الرمل يومياً، وإن اضطررتِ فاستخدمي قفازات واغسلي يديك. اغسلي الخضار جيداً، واطبخي اللحم جيداً، والبسي قفازات عند الزراعة. هذه الخطوات تقي من التوكسوبلازما.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 330000 FROM questions WHERE dev='nabd-team' AND title='عندي قطوة بالبيت، لازم أبعدها وأنا حامل؟ 🐱' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t1','حامل بتوأم 👶👶 إيه اللي يفرق في المتابعة؟','سؤال من أمهات التوائم.', @t2 - 420000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='حامل بتوأم 👶👶 إيه اللي يفرق في المتابعة؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'حمل التوأم يحتاج متابعة أكثر، لأن احتمال الولادة المبكرة وسكري الحمل وتسمم الحمل وفقر الدم أعلى. ستحتاجين سونار أكثر، وتغذية جيدة، وحديداً وحمض فوليك حسب الطبيب. وكثير من التوائم يولدون قبل الأسبوع 38.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 390000 FROM questions WHERE dev='nabd-team' AND title='حامل بتوأم 👶👶 إيه اللي يفرق في المتابعة؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','ميتى نقدر نعرف واش ولد ولا بنت؟','سؤال كيوصلنا بزاف 😄', @t2 - 480000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='ميتى نقدر نعرف واش ولد ولا بنت؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يظهر نوع الجنين غالباً في السونار بين الأسبوع 16 و20، حسب وضعية الطفل. ويمكن معرفته أبكر بتحليل دم خاص (NIPT) من الأسبوع 10، إن كان متاحاً في بلدك.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 450000 FROM questions WHERE dev='nabd-team' AND title='ميتى نقدر نعرف واش ولد ولا بنت؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','سونار التشوهات امتى؟ وبيكشف إيه بالظبط؟','سؤال بيتكرر في الشهر الرابع والخامس.', @t2 - 540000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='سونار التشوهات امتى؟ وبيكشف إيه بالظبط؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يُجرى عادة بين الأسبوع 18 و22، ويفحص أعضاء الجنين ونموه ومكان المشيمة وكمية السائل. معظم النتائج طبيعية، وإن ظهر شيء يحتاج متابعة سيشرح لكِ الطبيب الخطوات.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 510000 FROM questions WHERE dev='nabd-team' AND title='سونار التشوهات امتى؟ وبيكشف إيه بالظبط؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','عندي حكة قوية في كفوف إيديا ورجليا بالليل، ده طبيعي؟','سؤال مهم لازم كل حامل تعرف إجابته.', @t2 - 600000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='عندي حكة قوية في كفوف إيديا ورجليا بالليل، ده طبيعي؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الحكة الشديدة في الكفين وباطن القدمين، خاصة ليلاً وبدون طفح، قد تكون علامة ركود صفراوي في الحمل، ويحتاج تحليل دم ومتابعة. كلمي طبيبك اليوم.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 570000 FROM questions WHERE dev='nabd-team' AND title='عندي حكة قوية في كفوف إيديا ورجليا بالليل، ده طبيعي؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','التشققات بدت تبين في بطني 😢 فيه كريم يمنعها؟','سؤال يتكرر وايد.', @t2 - 660000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='التشققات بدت تبين في بطني 😢 فيه كريم يمنعها؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'التشققات تعتمد كثيراً على الوراثة وسرعة زيادة الوزن. ترطيب الجلد يخفف الحكة لكنه لا يمنعها تماماً. حافظي على زيادة وزن تدريجية. وتجنبي كريمات الريتينويد (الريتينول والتريتينوين) أثناء الحمل.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 630000 FROM questions WHERE dev='nabd-team' AND title='التشققات بدت تبين في بطني 😢 فيه كريم يمنعها؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','أقدر أعالج أسناني وأنا حامل؟ 🦷','سؤال بيوصلنا كتير: عندي ضرس بيوجعني ومش عارفة أروح ولا لا.', @t2 - 720000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='أقدر أعالج أسناني وأنا حامل؟ 🦷');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'علاج الأسنان آمن ومهم في الحمل، وأفضل وقت له الثلث الثاني. التخدير الموضعي آمن. التهاب اللثة شائع، فاهتمي بالفرشاة والخيط. أما التبييض التجميلي فيُؤجل لما بعد الولادة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 690000 FROM questions WHERE dev='nabd-team' AND title='أقدر أعالج أسناني وأنا حامل؟ 🦷' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','t2','شو اللقاحات اللي لازم آخدها وأنا حامل؟ 💉','سؤال عن لقاح الإنفلونزا والسعال الديكي.', @t2 - 780000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='شو اللقاحات اللي لازم آخدها وأنا حامل؟ 💉');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يُنصح بلقاح الإنفلونزا في الموسم بأي مرحلة من الحمل، ولقاح السعال الديكي (Tdap) في كل حمل (غالباً بين الأسبوع 16 و36 حسب بلدك) لحماية طفلك في أشهره الأولى، ولقاح كوفيد حسب التوصيات المحلية. أما اللقاحات الحية كالحصبة الألمانية فتُؤجل لما بعد الولادة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 750000 FROM questions WHERE dev='nabd-team' AND title='شو اللقاحات اللي لازم آخدها وأنا حامل؟ 💉' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
