INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'المشيمة الأمامية أو الخلفية كلاهما طبيعي. أما المشيمة المنخفضة في سونار الأسبوع 20 فغالباً ترتفع مع نمو الرحم، ويُعاد السونار حوالي الأسبوع 32. حتى ذلك الحين توجهي للمستشفى عند أي نزيف، واتبعي تعليمات طبيبك.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 810000 FROM questions WHERE dev='nabd-team' AND title='المشيمة طلعت منخفضة في السونار، أخاف؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','food','الأناناس بيعمل إجهاض؟ 🍍','سؤال من أكتر الأسئلة اللي بتوصلنا!', @t2 - 900000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='الأناناس بيعمل إجهاض؟ 🍍');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'لا توجد فاكهة ممنوعة بالكميات العادية. الأناناس لا يسبب إجهاضاً عند أكله بكميات طبيعية. تجنبي البابايا غير الناضجة (الخضراء). واغسلي الفاكهة جيداً، واحذري الإفراط في العصائر المحلاة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 870000 FROM questions WHERE dev='nabd-team' AND title='الأناناس بيعمل إجهاض؟ 🍍' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','food','الحلبة والقرفة والميرمية مسموحة؟ 🌿','سؤال يتكرر كثير عن الأعشاب.', @t2 - 960000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='الحلبة والقرفة والميرمية مسموحة؟ 🌿');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الكميات الصغيرة المستخدمة في الطبخ غالباً آمنة. أما شرب الأعشاب بكثرة أو كعلاج، مثل الحلبة والقرفة والميرمية والكركديه، فبعضها قد يسبب انقباضات أو يؤثر على الضغط والسكر. النعناع والزنجبيل بكميات معتدلة مقبولان غالباً. اسألي طبيبك قبل أي مشروب عشبي يومي.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 930000 FROM questions WHERE dev='nabd-team' AND title='الحلبة والقرفة والميرمية مسموحة؟ 🌿' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','food','نباتية وما باكل لحم، هل حملي رح يتأثر؟','سؤال من الأمهات النباتيات.', @t2 - 1020000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='نباتية وما باكل لحم، هل حملي رح يتأثر؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يمكن أن يكون الحمل النباتي صحياً مع تخطيط جيد. تحتاجين غالباً فيتامين B12 وحديداً وفيتامين د، وأحياناً أوميغا 3 من الطحالب. ومصادر البروتين: البقوليات والعدس والحمص والتوفو والمكسرات. أخبري طبيبك ليطلب التحاليل المناسبة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 990000 FROM questions WHERE dev='nabd-team' AND title='نباتية وما باكل لحم، هل حملي رح يتأثر؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','food','فيه أكل لازم أبعد عنه تماماً وأنا حامل؟','سؤال بيتكرر كتير عن الجبن والبيض واللحمة.', @t2 - 1080000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='فيه أكل لازم أبعد عنه تماماً وأنا حامل؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'كلي البيض واللحوم والدجاج مطهوة جيداً. تجنبي البيض النيء أو نصف المستوي، واللحم النيء أو الوردي من الداخل. الكبدة فيها فيتامين أ بكميات عالية، فقللي منها. واغسلي الخضار جيداً.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1050000 FROM questions WHERE dev='nabd-team' AND title='فيه أكل لازم أبعد عنه تماماً وأنا حامل؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
