INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'يُفضّل تأجيل صبغة الشعر حتى بعد الثلث الأول، واختيار صبغات خالية من الأمونيا في مكان جيد التهوية. الحناء الطبيعية آمنة غالباً. أما البروتين والكيراتين فيحتوي بعضه على الفورمالدهايد، فيُفضّل تأجيله لما بعد الولادة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1110000 FROM questions WHERE dev='nabd-team' AND title='ينفع أصبغ شعري أو أعمل بروتين وأنا حامل؟ 💇‍♀️' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','other','أبي أسوي عمرة وأنا حامل، يصير؟ 🕋','سؤال يتكرر وايد خصوصاً في المواسم.', @t2 - 1200000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='أبي أسوي عمرة وأنا حامل، يصير؟ 🕋');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الأفضل في الثلث الثاني ومع حمل غير معقد. خذي إذن طبيبك وتقريراً بعمر الحمل، فشركات الطيران قد تطلبه. اشربي ماءً كثيراً، واستريحي، واستخدمي الكرسي المتحرك عند التعب، وتجنبي الزحام الشديد. وتوجهي للطبيب عند أي نزيف أو ألم أو قلة حركة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1170000 FROM questions WHERE dev='nabd-team' AND title='أبي أسوي عمرة وأنا حامل، يصير؟ 🕋' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
