INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الجوال واللابتوب والواي فاي والمايكرويف وأجهزة تفتيش المطار لا يوجد دليل على أنها تضر الحمل. فقط لا تضعي اللابتوب على بطنك لفترات طويلة بسبب الحرارة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1230000 FROM questions WHERE dev='nabd-team' AND title='الجوال والمايكرويف وجهاز التفتيش بالمطار بيضروا الجنين؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
