INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'أغلب الحوامل يستطعن العمل حتى قرب الولادة. خذي فترات راحة، واشربي ماءً، وغيري وضعيتك كل ساعة، وتجنبي المواد الكيميائية والإشعاع والوقوف الطويل جداً. وأخبري طبيبك بطبيعة عملك.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1290000 FROM questions WHERE dev='nabd-team' AND title='شغلي فيه وقوف كتير، ده يأثر على الحمل؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
