INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'كثير من الأجنة يكونون في وضع مقعدي قبل الأسبوع 36 ثم يدورون للرأس. إن بقي مقعدياً بعد 36 أسبوعاً فقد يعرض الطبيب محاولة تدويره من الخارج (ECV) أو يناقش طريقة الولادة المناسبة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1350000 FROM questions WHERE dev='nabd-team' AND title='البيبي مقلوب في الأسبوع 32، يعدل ولا لازم قيصري؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
