INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'من العلامات: نزول السدادة المخاطية (إفراز مخاطي قد يكون وردياً)، ونزول البطن، وزيادة الضغط في الحوض، وانقباضات تزداد انتظاماً. نزول السدادة وحده لا يعني ولادة فورية. توجهي للمستشفى عند انقباضات منتظمة كل 5 دقائق، أو نزول ماء، أو نزيف، أو قلة الحركة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1410000 FROM questions WHERE dev='nabd-team' AND title='نزلت مني إفرازات مخاطية وردية، يعني قربت أولد؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
