INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الإبرة الظهرية من أكثر وسائل تسكين ألم الولادة فعالية، وهي آمنة لكِ وللطفل. قد تبطئ المرحلة الثانية قليلاً أو تسبب انخفاض ضغط أو صداعاً نادراً. لا تسبب ألم ظهر مزمناً حسب الدراسات. ناقشيها مع طبيبك قبل الولادة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1530000 FROM questions WHERE dev='nabd-team' AND title='الإبرة الظهرية آمنة؟ وبتعمل وجع ضهر بعدين؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
