INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'من علاماتها قبل الأسبوع 37: انقباضات منتظمة، أو ضغط في الحوض، أو ألم ظهر جديد، أو زيادة الإفرازات أو نزول ماء أو دم. توجهي للمستشفى فوراً. وإن قيل لكِ إن عنق الرحم قصير، فقد يصف الطبيب البروجستيرون أو غيره، فالتزمي بالخطة.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1590000 FROM questions WHERE dev='nabd-team' AND title='إيه علامات الولادة المبكرة اللي لازم أنتبه لها؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
