INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'حافظي على الجرح نظيفاً وجافاً، ولا ترفعي أشياء أثقل من طفلك 6 أسابيع، وامشي قليلاً يومياً لتقليل خطر الجلطات. راجعي الطبيب عند الاحمرار، أو الإفرازات، أو الحرارة، أو ألم يزيد. والتعافي الكامل يحتاج 6 إلى 8 أسابيع.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1650000 FROM questions WHERE dev='nabd-team' AND title='كيف أعتني بجرح القيصرية؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','mental','بعد الولادة بقيت بعيط كتير ومش طايقة نفسي 💔','رسالة بتوصلنا كتير من الأمهات.', @t2 - 1740000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='بعد الولادة بقيت بعيط كتير ومش طايقة نفسي 💔');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'تقلب المزاج والقلق شائعان في الحمل وبعد الولادة، ومشاعرك مفهومة 🤍. تكلمي مع شخص تثقين به، ونامي واستريحي قدر الإمكان، واخرجي للمشي. إن استمر الحزن أو القلق أكثر من أسبوعين، أو أثّر على نومك وأكلك، فكلمي طبيبك، فهذا شائع وقابل للعلاج. وإن راودتك أفكار بإيذاء نفسك فاطلبي المساعدة فوراً من الطوارئ.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1710000 FROM questions WHERE dev='nabd-team' AND title='بعد الولادة بقيت بعيط كتير ومش طايقة نفسي 💔' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
