INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الاحتقان يتحسن بالرضاعة المتكررة، وكمادات باردة بعد الرضعة. إن ظهر احمرار وألم في منطقة من الثدي مع حرارة أو أعراض كالإنفلونزا، فقد يكون التهاباً يحتاج طبيباً وأحياناً مضاداً حيوياً. استمري في الرضاعة لأنها تساعد على الشفاء.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1830000 FROM questions WHERE dev='nabd-team' AND title='صدري محتقن وأحمر وعندي سخونية، أبطل رضاعة؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
