INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'حليب الأم المشفوط يبقى حوالي 4 ساعات في درجة الغرفة، و4 أيام في الثلاجة، وحتى 6 أشهر في الفريزر. سخنيه في ماء دافئ لا في المايكرويف، ولا تعيدي تجميده بعد إذابته.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 1890000 FROM questions WHERE dev='nabd-team' AND title='كم يقعد الحليب المشفوط في الثلاجة؟ 🍼' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
