INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'الصفار الخفيف شائع بين اليوم الثاني والخامس ويختفي خلال أسبوعين. توجهي للطبيب فوراً إن ظهر في أول 24 ساعة، أو امتد للبطن والساقين، أو كان الطفل خاملاً أو لا يرضع جيداً، أو كان البراز فاتحاً (أبيض أو رمادي)، أو استمر بعد أسبوعين.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2010000 FROM questions WHERE dev='nabd-team' AND title='البيبي لونه أصفر في اليوم التالت، ده خطر؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','baby','كيف أنوّم البيبي بأمان؟ على ظهره ولا بطنه؟ 😴','سؤال يتكرر وايد.', @t2 - 2100000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='كيف أنوّم البيبي بأمان؟ على ظهره ولا بطنه؟ 😴');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'نوّمي طفلك دائماً على ظهره، في سرير خاص بمرتبة صلبة، بدون وسائد أو ألعاب أو أغطية ثقيلة، وفي غرفتك أول 6 أشهر. تجنبي النوم معه في نفس السرير، خاصة مع التعب أو التدخين، وتجنبي ارتفاع حرارة الغرفة. هذا يقلل خطر موت الرضيع المفاجئ.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2070000 FROM questions WHERE dev='nabd-team' AND title='كيف أنوّم البيبي بأمان؟ على ظهره ولا بطنه؟ 😴' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','baby','نديرو الما ولا اليانسون للبيبي؟','سؤال كيتعاود بزاف من الجدات والماماوات.', @t2 - 2160000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='نديرو الما ولا اليانسون للبيبي؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'قبل 6 أشهر لا يحتاج الرضيع ماءً ولا أعشاباً، فحليب الأم أو الصناعي يكفيه حتى في الحر. والأعشاب قد تقلل رضاعته أو تكون غير آمنة. بعد 6 أشهر يمكن إعطاء رشفات ماء مع الأكل.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2130000 FROM questions WHERE dev='nabd-team' AND title='نديرو الما ولا اليانسون للبيبي؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
