INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'جشئي طفلك أثناء الرضعة وبعدها، وحركي ساقيه كالدراجة، ودلكي بطنه باتجاه عقارب الساعة. ووقت البطن وهو مستيقظ يساعد. أغلب قطرات المغص لم تثبت فعاليتها، فاسألي الطبيب قبل أي دواء.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2190000 FROM questions WHERE dev='nabd-team' AND title='ابني عنده غازات وبيتلوى بعد الرضعة، أعمل إيه؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
INSERT INTO questions (dev, nick, cat, title, body, t, ac) SELECT 'nabd-team','فريق نبض','baby','امتى ابني يقعد ويحبي ويمشي؟','سؤال يتكرر كثير عن مراحل النمو.', @t2 - 2280000, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM questions WHERE dev='nabd-team' AND title='امتى ابني يقعد ويحبي ويمشي؟');
INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'تقريبياً: الابتسامة 6 إلى 8 أسابيع، والتقلب 4 إلى 6 أشهر، والجلوس 6 إلى 8 أشهر، والحبو 7 إلى 10 أشهر، والمشي 9 إلى 15 شهراً، وأول كلمة حوالي السنة. لكل طفل سرعته. أخبري الطبيب إن تأخر بوضوح، أو فقد مهارة كان يجيدها.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2250000 FROM questions WHERE dev='nabd-team' AND title='امتى ابني يقعد ويحبي ويمشي؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
