INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'صعوبة النوم شائعة خاصة في الثلث الأخير. جربي:\n• موعد نوم ثابت، وتقليل الشاشات قبل النوم بساعة.\n• وسادة حمل أو وسادة بين الركبتين.\n• تقليل الشرب قبل النوم مباشرة، وعدم تناول القهوة بعد العصر.\nلا تأخذي أي حبوب منومة أو أعشاب دون سؤال الطبيب.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2310000 FROM questions WHERE dev='nabd-team' AND title='الأرق قاتلني في الشهر الأخير 😩' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
