INSERT INTO answers (qid, dev, nick, ai, body, t) SELECT id, 'nabd-team', 'فريق نبض', 0, 'التورم الخفيف في القدمين آخر اليوم طبيعي في الحمل. ارفعي قدميكِ، وتجنبي الوقوف الطويل، واشربي ماءً، وقللي الملح الزائد. أما التورم المفاجئ في الوجه واليدين، أو التورم مع صداع وزغللة، فيحتاج الطبيب اليوم.\n\nللتثقيف فقط ولا تغني عن طبيبك 🤍', @t2 - 2370000 FROM questions WHERE dev='nabd-team' AND title='رجلي ورمت آخر النهار، ده عادي؟' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev='nabd-team') x);
